-- STEP 37 (APPLIED 2026-10-18): UHAS 2024/2025 cut-offs for 17 programmes (unverified, secondary source).
-- Source: https://ghstudents.com/uhas-cut-off-points/ (table headed WASSCE 2024/2025; page dates conflict, so the year is uncertain). Matched by name.
with v(name, agg) as (values
('Bachelor of Public Health (Disease Control)',19),('Bachelor of Public Health (Health Information)',23),('Bachelor of Public Health (Health Promotion)',23),('Bachelor of Public Health (Nutrition)',19),('Bachelor of Dietetics',17),('Bachelor of Diagnostic Imaging (Radiography)',17),('Bachelor of Orthotics and Prosthetics',18),('Bachelor of Physiotherapy',17),('Bachelor of Speech, Language and Hearing Sciences',18),('Doctor of Medical Laboratory Science',15),('Bachelor of Science in Biochemistry and Molecular Biology',18),('Bachelor of Medicine, Bachelor of Surgery (MBChB)',8),('Bachelor of Nursing',12),('Bachelor of Midwifery',12),('Bachelor of Public Health Nursing',14),('Doctor of Pharmacy',8),('Bachelor of Sports and Exercise Medical Sciences',18)),
p as (select pr.id, v.agg from public.programs pr join public.schools s on s.id = pr.school_id join v on v.name = pr.name where s.name = 'University of Health and Allied Sciences' and coalesce(pr.level,'Undergraduate') <> 'Masters'),
c as (insert into public.program_cutoffs (program_id, year, cutoff_aggregate) select id, 2024, agg from p on conflict (program_id, year) do update set cutoff_aggregate = excluded.cutoff_aggregate returning 1),
u as (update public.programs set verified = false, entry_note = trim(both ' ' from coalesce(entry_note || ' ', '') || 'Cut-off is the 2024/2025 WASSCE figure from a secondary site (ghstudents.com); unverified. Matched by programme name, which may differ slightly from UHAS''s title.') where id in (select id from p) returning 1)
select (select count(*) from c) as cutoffs, (select count(*) from u) as updated;
